Path('Zpass/scripts/approval-translations.json').write_text(json.dumps({locale:dict(zip(keys,values)) for locale,values in rows.items()},ensure_ascii=False,indent=2),encoding='utf-8')
for root in ['ZPass-Modern/resources/assets/lang/json','Zpass/public/resources/assets/lang/json']:
 for locale,values in rows.items():
  p=Path(root)/(locale+'.json');data=json.loads(p.read_text(encoding='utf-8-sig'));data.update(dict(zip(keys,values)));p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
